def logo_png_bytes() -> bytes:
    return base64.b64decode(_PNG_B64)


def logo_ico_bytes() -> bytes:
    return base64.b64decode(_ICO_B64)


def logo_pil_image():
    """RGBA PIL Image of the brand logo (always from embedded bytes)."""
    from PIL import Image

    return Image.open(io.BytesIO(logo_png_bytes())).convert("RGBA")


def materialize_icon_file(directory: str, filename: str = "dcs_norway_brand.ico") -> str:
    """Write embedded ICO for Tk iconbitmap / Qt window icon."""
    os.makedirs(directory, exist_ok=True)
    path = os.path.join(directory, filename)
    data = logo_ico_bytes()
    if os.path.exists(path) and os.path.getsize(path) == len(data):
        with open(path, "rb") as f:
            if f.read() == data:
                return path
    with open(path, "wb") as f:
        f.write(data)
    return path
